	auto net = std::make_shared<torch::jit::Module>(module);
	net->to(device);
	net->eval();
	time = GetTickCount();
	cv::Mat image = cv::imread("12_Group_Group_12_Group_Group_12_728.jpg");
	JitDBFaceDetect(net, image);
	std::printf("time:%f \r\n", static_cast<float>(GetTickCount() - time) / 1000);
}
void JitDBFaceDetect(std::shared_ptr<torch::jit::Module> model, cv::Mat image, float threshold , float nms_iou ) {
    cv::Mat padimage = padImage(image);  
   float mean[3] = { 0.408, 0.447, 0.47 };
   float std[3] = { 0.289, 0.274, 0.278 };
   padimage = setNormMat(0, padimage, mean, std);
    torch::Tensor torch_image = torch::from_blob(padimage.data, { padimage.rows, padimage.cols, 3 }, torch::kByte);
    torch_image = torch_image.permute({ 2,0,1});
    torch_image = torch_image.toType(torch::kFloat);
    torch_image = torch_image.unsqueeze(0);
    std::vector<torch::jit::IValue> jitdata;
    jitdata.push_back(torch_image);
    auto ret = model->forward(jitdata).toTensor(); //error ,it can't forward
}
cv::Mat padImage(const cv::Mat& image, int stride) {
    int w = image.cols;
    if (image.cols % stride != 0)
        w = image.cols + (stride - (image.cols % stride));
    int h = image.rows;
    if (image.rows % stride != 0)
        h = image.rows + (stride - (image.rows % stride));
    if (cv::Size(w, h) == image.size())
        return image;
    cv::Mat output(h, w, image.type(), cv::Scalar(0));
    image.copyTo(output(cv::Rect(0, 0, image.cols, image.rows)));
    return output;
}
cv::Mat setNormMat(int n, const cv::Mat& image, float mean[3], float std[3]) {
    float scale = 1 / 255.0;
    cv::Mat inputframe = image;
    cv::resize(inputframe, inputframe, cv::Size(image.cols, image.rows));
    inputframe.convertTo(inputframe, CV_32F, scale);
    cv::Mat ms[3];
    for (int c = 0; c < 3; ++c)
        ms[c] = cv::Mat(image.rows, image.cols, CV_32F, image.data[c]);
    split(inputframe, ms);
    for (int c = 0; c < 3; ++c)
        ms[c] = (ms[c] - mean[c]) / std[c];
    return inputframe;
}
